<script setup>
import { computed, ref } from 'vue'; import CircuitScene from './components/CircuitScene.vue'; import ComponentLibrary from './components/ComponentLibrary.vue'; import SchematicView from './components/SchematicView.vue'; import { formatCurrent, simulateCircuit } from './engine/simulator';
const view=ref('3d'), selected=ref(null), placed=ref(['battery','resistor','led']), exercise=ref('led'), result=computed(()=>simulateCircuit(exercise.value)); const status=computed(()=>({...result.value,currentLabel:formatCurrent(result.value.current)})); function add(c){placed.value.push(c.id);selected.value=c}
</script>
<template><main class="app-shell"><header class="topbar"><div class="brand"><div class="brand-mark">⌁</div><div><span class="eyebrow">Electronics playground</span><h1>CircuitForge Lab</h1><p>Laboratorio 3D para aprender electrónica.</p></div></div><div class="simulation-actions"><button class="button" :class="{active:exercise==='led'}" @click="exercise='led'">▶ LED seguro</button><button class="button" :class="{active:exercise==='overload'}" @click="exercise='overload'">⚡ Sobrecarga</button><button class="button danger-button" :class="{active:exercise==='short'}" @click="exercise='short'">✹ Cortocircuito</button></div></header><section class="editor card"><ComponentLibrary :selected-id="selected?.id" @select="selected=$event" @add="add"/><section class="editor-stage"><div class="stage-toolbar"><div><span class="eyebrow">Editor interactivo</span><h2>{{view==='3d'?'Protoboard 3D':'Diagrama eléctrico'}}</h2><p class="stage-detail">{{status.detail}}</p></div><div class="view-switch"><button class="mini-button" :class="{active:view==='3d'}" @click="view='3d'">3D</button><button class="mini-button" :class="{active:view==='diagram'}" @click="view='diagram'">Esquema</button></div></div><div class="stage-board" :class="`state-${status.status}`"><CircuitScene v-if="view==='3d'"/><SchematicView v-else/><div class="simulation-banner" :class="status.status"><strong>{{status.label}}</strong><span>{{status.currentLabel}} · {{status.power.toFixed ? status.power.toFixed(3) : '∞'}} W</span></div><div class="placed-components"><button v-for="(id,i) in placed" :key="`${id}-${i}`" class="placed-chip">{{id.toUpperCase()}} #{{i+1}}</button></div></div></section><aside class="inspector"><span class="eyebrow">Inspector eléctrico</span><h3>{{selected?.name||'Selecciona un componente'}}</h3><p>{{selected?.description||'Añade un componente desde la biblioteca para consultar sus pines y estado.'}}</p><dl><div><dt>Voltaje</dt><dd>{{status.voltage.toFixed(1)}} V</dd></div><div><dt>Corriente</dt><dd>{{status.currentLabel}}</dd></div><div><dt>Salida</dt><dd>{{Number.isFinite(status.output)?status.output.toFixed(2):'∞'}} V</dd></div><div><dt>Estado</dt><dd :class="`text-${status.status}`">{{status.label}}</dd></div></dl></aside></section><section class="card education-note"><span class="eyebrow">Análisis del circuito</span><h2>{{status.label}}</h2><p>{{status.detail}}</p><div class="exercise-picker"><button class="button" :class="{active:exercise==='divider'}" @click="exercise='divider'">Divisor de voltaje</button><button class="button" :class="{active:exercise==='inverter'}" @click="exercise='inverter'">Inversor NPN</button></div></section><footer>Construido con Vue, Vite y Three.js · <a href="https://github.com/uppy19d0/circuitforge-lab" target="_blank">Repositorio en GitHub</a></footer></main></template>
